css:
body {
    font-family: "Times New Roman", Times, serif;
    margin: 20px;
    line-height: 1.4;
    color: #333;
}

table {
    width: 100%;
    border-collapse: collapse;
    font-family: "Times New Roman", Times, serif;
    font-size: 12px;
    margin: 10px 0;
}

th, td {
    border: 1px solid #000;
    padding: 10px 12px;
    text-align: left;
    vertical-align: middle;
}

td:first-child {
    font-weight: 500;
    width: 50%;
}

td:nth-child(2), td:nth-child(3) {
    width: 25%;
    text-align: center;
    font-family: Arial, sans-serif;
}

.line1 {
    border: none;
    height: 3px;
    background-color: #000;
    margin: 5px 0;
}

.line2 {
    border: none;
    height: 1px;
    background-color: #666;
    margin: 2px 0 15px 0;
}

center {
    margin: 15px 0;
}

u {
    text-decoration: underline;
    text-underline-offset: 3px;
}

b {
    font-weight: bold;
}

tr:nth-child(even) {
    background-color: #f9f9f9;
}

tr:hover {
    background-color: #f5f5f5;
}

/* Header rows styling */
tr:first-child td {
    background-color: #f0f0f0;
    font-weight: bold;
    font-size: 14px;
}

/* Total rows styling */
tr:has(td b) {
    background-color: #e8e8e8;
    font-weight: bold;
}


.print-wrapper {
    width: 100%;
    max-width: 750px;
    margin: 0 auto;
    padding: 0 20px;
}

.pdf-page {
    height: 1122px; /* A4 height at 96 DPI */
    position: relative;
    page-break-after: always;
    padding: 40px 30px 100px 30px; /* top, right, bottom, left */
    box-sizing: border-box;
}

.footer-fixed {
    position: absolute;
    bottom: 20px;
    left: 30px;
    right: 30px;
    text-align: center;
    font-size: 11px;
}
